package com.yonlab.vision;
import android.content.Context;import android.graphics.*;import android.os.SystemClock;
import ai.onnxruntime.*;import org.tensorflow.lite.*;import org.json.*;
import java.io.*;import java.nio.*;import java.security.*;import java.util.*;

/** Image-query retrieval against an explicitly curated, SHA-checked demo gallery. */
final class ImageRetrieval {
 private static final String PREPROCESS="image-retrieval-v1";
 private static final Map<String,float[]> CACHE=Collections.synchronizedMap(new LinkedHashMap<String,float[]>(128,.75f,true){protected boolean removeEldestEntry(Map.Entry<String,float[]> e){return size()>256;}});
 private static final Map<String,String> PIXELS=Collections.synchronizedMap(new LinkedHashMap<String,String>(128,.75f,true){protected boolean removeEldestEntry(Map.Entry<String,String> e){return size()>128;}});
 static String expected(String id){if(AddedVisionModels.retrieval(id))return AddedVisionModels.sha(id);switch(id){case "search-tinyclip-q8":return "bbf8426b0e548881dcfd9257030dd6139fceeeb4808994968b882ecc3ada291f";case "search-mobilenet-v3-small":return "bbbb4c51a55a53905af1daec995ca1aae355046f8839bb8c9f5ce9271394bc40";case "search-mobilenet-v3-large":return "11af3c560dfeed7737cb4c03c23bf52a8403020784192d4dea0b74862a12828d";default:throw new IllegalArgumentException("retrieval model");}}
 static void run(Context c,String id,Bitmap input,OneModelRunner.Cancel cancel,OneModelRunner.Result r)throws Exception{
  long started=SystemClock.elapsedRealtime();Encoder engine=new Encoder(c,id);r.engineCreated=true;r.modelSha256=engine.sha;r.loadMs=SystemClock.elapsedRealtime()-started;
  try{long infer=SystemClock.elapsedRealtime();String queryPixels=pixelHash(input);float[] query=engine.embed(input);JSONArray raw=readCatalog(c);List<DemoStore.Item> gallery=new ArrayList<>();for(int i=0;i<raw.length();i++){JSONObject row=raw.getJSONObject(i);if(row.optBoolean("galleryEligible")&&"image".equals(row.optString("type")))gallery.add(DemoStore.find(c,row.getString("id")));}if(gallery.size()<3)throw new IOException("사진 검색 자료를 준비하세요");if(gallery.size()>96)throw new IOException("검색 앨범은 96장 이하로 구성하세요");MessageDigest catalogHash=MessageDigest.getInstance("SHA-256");for(DemoStore.Item item:gallery)catalogHash.update((item.id+":"+item.sha256+"\n").getBytes("UTF-8"));List<Match> ranked=new ArrayList<>();int excluded=0,cached=0,indexed=0;
   for(DemoStore.Item item:gallery){ExpansionImageRunner.check(cancel);String key=engine.sha+":"+PREPROCESS+":"+item.sha256;float[] vector=CACHE.get(key);String candidatePixels=PIXELS.get(item.sha256);Bitmap image=null;try{if(vector==null||candidatePixels==null){image=ImageIO.load(c,DemoStore.uri(c,item),1600);candidatePixels=pixelHash(image);PIXELS.put(item.sha256,candidatePixels);if(vector==null){vector=engine.embed(image);CACHE.put(key,vector);indexed++;}else cached++;}else cached++;if(queryPixels.equals(candidatePixels)){excluded++;continue;}ranked.add(new Match(item,RetrievalMath.cosine(query,vector)));}finally{if(image!=null)image.recycle();}}
   ranked.sort((a,b)->{int order=Double.compare(b.score,a.score);return order!=0?order:a.item.id.compareTo(b.item.id);});JSONArray ranking=new JSONArray();StringBuilder detail=new StringBuilder();for(int i=0;i<ranked.size();i++){Match match=ranked.get(i);ranking.put(new JSONObject().put("rank",i+1).put("id",match.item.id).put("title",match.item.title).put("sha256",match.item.sha256).put("cosine",match.score));if(i<5)detail.append(i+1).append(". ").append(match.item.title).append("  ").append(String.format(Locale.ROOT,"%.3f",match.score)).append('\n');}
   r.image=mosaic(c,ranked,cancel);r.summary=ranked.isEmpty()?"다른 사진을 앨범에 추가하세요":"비슷한 사진 · "+ranked.get(0).item.title;r.detail=detail.toString();r.metrics.put("ranking",ranking).put("galleryCount",gallery.size()).put("rankedCount",ranked.size()).put("gallerySha256",hex(catalogHash.digest())).put("queryPixelSha256",queryPixels).put("exactSelfExcluded",excluded).put("embeddingDimensions",query.length).put("indexNewEmbeddings",indexed).put("indexCacheHits",cached).put("preprocessingContract",engine.preprocessContract()).put("cacheContract",PREPROCESS+" + encoderSHA + candidateEncodedSHA; vectors never mixed between encoders").put("pipeline","actual image encoder → L2-normalized vectors → same-gallery cosine retrieval");r.inferenceMs=SystemClock.elapsedRealtime()-infer;
  }finally{engine.close();r.engineCloseReturned=true;}
 }
 private static JSONArray readCatalog(Context c)throws Exception{try(InputStream in=c.getAssets().open("one/demos.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>2*1024*1024)throw new IOException("gallery catalog size");out.write(b,0,n);}return new JSONObject(out.toString("UTF-8")).getJSONArray("items");}}
 private static final class Match{final DemoStore.Item item;final double score;Match(DemoStore.Item item,double score){this.item=item;this.score=score;}}
 private static Bitmap mosaic(Context c,List<Match> ranked,OneModelRunner.Cancel cancel)throws Exception{int count=Math.min(3,ranked.size());int width=420,height=330;Bitmap out=Bitmap.createBitmap(Math.max(1,count)*width,height,Bitmap.Config.ARGB_8888);boolean success=false;try{Canvas canvas=new Canvas(out);canvas.drawColor(0xfff5f8ff);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);for(int i=0;i<count;i++){ExpansionImageRunner.check(cancel);Match m=ranked.get(i);Bitmap image=ImageIO.load(c,DemoStore.uri(c,m.item),640);try{float scale=Math.min(396f/image.getWidth(),250f/image.getHeight());float w=image.getWidth()*scale,h=image.getHeight()*scale,left=i*width+12+(396-w)/2,top=12+(250-h)/2;canvas.drawBitmap(image,null,new RectF(left,top,left+w,top+h),p);}finally{image.recycle();}p.setColor(0xff071b45);p.setTextSize(20);String title=m.item.title;if(title.length()>20)title=title.substring(0,19)+"…";canvas.drawText((i+1)+" · "+title,i*width+14,290,p);p.setTextSize(17);p.setColor(0xff0068f8);canvas.drawText("유사도 "+String.format(Locale.ROOT,"%.3f",m.score),i*width+14,316,p);}success=true;return out;}finally{if(!success)out.recycle();}}
 private static String pixelHash(Bitmap image)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");ByteBuffer row=ByteBuffer.allocate(image.getWidth()*4+8).order(ByteOrder.BIG_ENDIAN);row.putInt(image.getWidth()).putInt(image.getHeight());digest.update(row.array(),0,8);int[] pixels=new int[image.getWidth()];for(int y=0;y<image.getHeight();y++){image.getPixels(pixels,0,pixels.length,0,y,pixels.length,1);row.clear();for(int value:pixels)row.putInt(value);digest.update(row.array(),0,pixels.length*4);}return hex(digest.digest());}
 private static String hex(byte[] digest){StringBuilder s=new StringBuilder();for(byte b:digest)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 private static final class Encoder implements AutoCloseable{
  final String sha;final boolean clip;private OrtSession ort;private OrtEnvironment env;private Interpreter lite;private AddedVisionOnnx extra;
  Encoder(Context c,String id)throws Exception{sha=expected(id);clip="search-tinyclip-q8".equals(id);int threads=OneExecutionSettings.threads(c);
   if(AddedVisionModels.retrieval(id)){extra=new AddedVisionOnnx(c,id);return;}
   if(clip){byte[] bytes;try(InputStream in=c.getAssets().open("one/models/search-tinyclip-vision-q8.onnx")){ByteArrayOutputStream data=new ByteArrayOutputStream();byte[] block=new byte[65536];int n;while((n=in.read(block))!=-1){if(data.size()+n>32*1024*1024)throw new IOException("retrieval model size");data.write(block,0,n);}bytes=data.toByteArray();}if(!sha.equals(hex(MessageDigest.getInstance("SHA-256").digest(bytes))))throw new IOException("retrieval model SHA");env=OrtEnvironment.getEnvironment();try(OrtSession.SessionOptions options=new OrtSession.SessionOptions()){options.setIntraOpNumThreads(threads);options.setInterOpNumThreads(1);ort=env.createSession(bytes,options);}if(ort.getNumInputs()!=1||!ort.getInputNames().contains("pixel_values")||!ort.getOutputNames().contains("image_embeds")){ort.close();throw new IOException("retrieval ONNX contract");}}
   else{OneLiteAsset asset=new OneLiteAsset(c,id+".tflite");if(!sha.equals(asset.sha256))throw new IOException("retrieval model SHA");lite=new Interpreter(asset.bytes,new Interpreter.Options().setNumThreads(threads));int[] shape=lite.getInputTensor(0).shape();if(!Arrays.equals(shape,new int[]{1,224,224,3})||lite.getInputTensor(0).dataType()!=DataType.FLOAT32||lite.getOutputTensor(0).dataType()!=DataType.FLOAT32){lite.close();throw new IOException("retrieval TFLite contract");}}
  }
  String preprocessContract(){return extra!=null?"ImageNet RGB shortest-side256 / center224, mean=[.485,.456,.406], std=[.229,.224,.225]; pooled pre-classifier512 → L2":clip?"CLIP shortest-side224 bicubic/center224 RGB/255 with published CLIP mean/std":"MobileNetV3 embedder RGB resize224 /255; model TFLite metadata mean0,std255";}
  float[] embed(Bitmap image)throws Exception{if(extra!=null)return extra.run(image,result->{Object value=AddedVisionOnnx.output(result,"yon_embedding");if(!(value instanceof float[][])||((float[][])value).length!=1||((float[][])value)[0].length!=512)throw new IOException("embedding dimensions");return RetrievalMath.normalized(((float[][])value)[0]);});Bitmap crop=null;try{int area=224*224;int[] pixels;if(clip)pixels=clipPixels(image);else{crop=Bitmap.createScaledBitmap(image,224,224,true);pixels=new int[area];crop.getPixels(pixels,0,224,0,0,224,224);}
    if(clip){float[] values=new float[3*area],mean={.48145466f,.4578275f,.40821073f},std={.26862954f,.26130258f,.27577711f};for(int i=0;i<area;i++)for(int ch=0;ch<3;ch++){float value=((pixels[i]>>(16-8*ch))&255)/255f;values[ch*area+i]=(value-mean[ch])/std[ch];}try(OnnxTensor tensor=OnnxTensor.createTensor(env,FloatBuffer.wrap(values),new long[]{1,3,224,224});OrtSession.Result result=ort.run(Collections.singletonMap("pixel_values",tensor))){Object v=result.get("image_embeds").orElseThrow(()->new IOException("embedding output")).getValue();if(!(v instanceof float[][])||((float[][])v).length!=1||((float[][])v)[0].length!=512)throw new IOException("embedding dimensions");return RetrievalMath.normalized(((float[][])v)[0]);}}
    ByteBuffer values=ByteBuffer.allocateDirect(area*3*4).order(ByteOrder.nativeOrder());for(int pixel:pixels){values.putFloat(((pixel>>>16)&255)/255f);values.putFloat(((pixel>>>8)&255)/255f);values.putFloat((pixel&255)/255f);}values.rewind();int[] output=lite.getOutputTensor(0).shape();if(output.length!=2||output[0]!=1||output[1]<2||output[1]>4096)throw new IOException("embedding output shape");float[][] vector=new float[1][output[1]];lite.run(values,vector);return RetrievalMath.normalized(vector[0]);
   }finally{if(crop!=null&&crop!=image)crop.recycle();}}
  private static int[] clipPixels(Bitmap image){int w=image.getWidth(),h=image.getHeight(),small=Math.min(w,h);int rw=w<=h?224:(int)(224L*w/small),rh=h<=w?224:(int)(224L*h/small),left=(rw-224)/2,top=(rh-224)/2;int[] source=new int[w*h],out=new int[224*224];image.getPixels(source,0,w,0,0,w,h);
   // Catmull-Rom bicubic RGB center crop without allocating a potentially huge resized panorama.
   for(int y=0;y<224;y++){double sy=(y+top+.5)*h/rh-.5;int iy=(int)Math.floor(sy);for(int x=0;x<224;x++){double sx=(x+left+.5)*w/rw-.5;int ix=(int)Math.floor(sx);double[] rgb=new double[3];double total=0;for(int ky=-1;ky<=2;ky++){int yy=Math.max(0,Math.min(h-1,iy+ky));double wy=cubic(sy-(iy+ky));for(int kx=-1;kx<=2;kx++){int xx=Math.max(0,Math.min(w-1,ix+kx));double weight=wy*cubic(sx-(ix+kx));int value=source[yy*w+xx];total+=weight;rgb[0]+=((value>>>16)&255)*weight;rgb[1]+=((value>>>8)&255)*weight;rgb[2]+=(value&255)*weight;}}out[y*224+x]=Color.rgb(channel(rgb[0]/total),channel(rgb[1]/total),channel(rgb[2]/total));}}return out;}
  private static int channel(double v){return Math.max(0,Math.min(255,(int)Math.round(v)));}
  private static double cubic(double x){x=Math.abs(x);return x<=1?1.5*x*x*x-2.5*x*x+1:x<2?-.5*x*x*x+2.5*x*x-4*x+2:0;}
  public void close()throws Exception{if(extra!=null){extra.close();extra=null;}if(lite!=null){lite.close();lite=null;}if(ort!=null){ort.close();ort=null;}}
 }
}
